    },
    {
      "company": "CleanOps",
      "type": "customer_overlap",
      "severity": "manageable",
      "rationale": "CleanOps serves commercial cleaning businesses with SaaS — commercial cleaning companies are a core vertical for field service scheduling platforms like Cadence (crew dispatch, job scheduling, customer communication). Significant shared customer segment with Cadence's target market."
    },
    {
      "company": "LaborLink",
      "type": "adjacent",
      "severity": "manageable",
      "rationale": "LaborLink targets skilled trades businesses with staffing SaaS — the same SMB contractor base that Cadence serves for scheduling and dispatch. While staffing and scheduling are distinct functions, they are often bundled or adjacent in the SMB field service workflow, and shared customers could create channel conflict or product confusion."
    }
  ]
}
